(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["physical-diagnosis-2-exam-1"]={"title":"Physical Diagnosis 2 Exam 1","sections":[{"id":"encounter","title":"The Encounter, Presentation & Documentation","style":"--acc:#4a5c24;--acc-bg:#e6e8e0;--acc-zebra:#f2f4f0;--acc-ink:#3a481c"},{"id":"skin-structure","title":"Skin — Structure & Function","style":"--acc:#6b7f35;--acc-bg:#eaede3;--acc-zebra:#f5f6f1;--acc-ink:#536329"},{"id":"vocabulary","title":"Descriptive Vocabulary — Distribution & Configuration","style":"--acc:#8a7526;--acc-bg:#efece1;--acc-zebra:#f7f5f0;--acc-ink:#6c5b1e"},{"id":"morphology","title":"Primary & Secondary Morphology","style":"--acc:#8f5b2a;--acc-bg:#efe8e1;--acc-zebra:#f7f4f0;--acc-ink:#704721"},{"id":"abnormal","title":"Abnormal Findings — Skin, Hair & Nails","style":"--acc:#7d3f52;--acc-bg:#ede4e7;--acc-zebra:#f6f2f3;--acc-ink:#623140"},{"id":"technique","title":"Performing the Skin Examination","style":"--acc:#3f5b6b;--acc-bg:#e4e8ea;--acc-zebra:#f2f4f5;--acc-ink:#314753"},{"id":"l3-scope","title":"★ WHAT SHE TOOK OUT OF SCOPE","style":"--acc:#b8860b;--acc-bg:#f7efd9;--acc-zebra:#fbf7ec;--acc-ink:#7a5a08"},{"id":"l3-memory","title":"★ “VERY IMPORTANT TO COMMIT TO MEMORY”","style":"--acc:#8c1d12;--acc-bg:#f7e3e0;--acc-zebra:#fbf1f0;--acc-ink:#6b1610"},{"id":"l3-history","title":"History & Symptom Patterns","style":"--acc:#4a5c24;--acc-bg:#e8ecdd;--acc-zebra:#f4f6ee;--acc-ink:#3a4a1c"},{"id":"l3-inspect","title":"Inspection","style":"--acc:#6b7f35;--acc-bg:#eaeee0;--acc-zebra:#f5f7f0;--acc-ink:#54642a"},{"id":"l3-acuity","title":"Acuity, Fields & Motility","style":"--acc:#3a5a40;--acc-bg:#e3ece5;--acc-zebra:#f1f5f2;--acc-ink:#2c452f"},{"id":"l3-pupils","title":"The Pupils","style":"--acc:#5f4a7d;--acc-bg:#e9e4f0;--acc-zebra:#f4f1f8;--acc-ink:#493a60"},{"id":"l3-fundus","title":"Fundoscopy & Trauma","style":"--acc:#7a4a2e;--acc-bg:#f0e7e1;--acc-zebra:#f8f3f0;--acc-ink:#5f3922"}],"rows":[{"t":"Oral presentation — opening","d":"Open with the past medical history and the chief complaint. Then pertinent positives and negatives from BOTH history and physical. Follow mostly the order you obtained them. Try not to read your notes.","s":0},{"t":"Oral presentation — the test","d":"A good presentation leads your facilitator to the same differential you formulated. It is a well-organised vignette, not the written note read aloud; the goal is to help listeners visualise the patient.","s":0},{"t":"Focused vs comprehensive","d":"A focused encounter narrows BOTH the history and the examination — history of present illness, review of systems, past medical history, social history, family history, medications and allergies are all focused. It is not a comprehensive encounter written up more briefly.","s":0},{"t":"Focused encounter — required output","d":"Differentials, laboratory and imaging studies, a diagnosis, and a treatment plan including patient education. Narrowing the data gathered does not narrow what you must conclude.","s":0},{"t":"History and physical vs SOAP","d":"The history and physical is comprehensive (whole history, head-to-toe). The SOAP note is problem-focused: Subjective (what the patient said), Objective (what you found, always with a general impression), Assessment (what you concluded), Plan (what you will do).","s":0},{"t":"Documentation rules that cost marks","d":"Describe findings — never 'normal', 'abnormal' or 'unremarkable'. NO abbreviations, with no exceptions. Keep subjective and objective in their own sections. If you did not do it, document why — never invent a finding. Never write a note with another student.","s":0},{"t":"Communication","d":"Adapt style and content for each patient. When someone else supplies the answers, ALWAYS look at and interact with the patient, not the person answering. Accept feedback and modify behaviour; different facilitators give different feedback, and that is expected.","s":0},{"t":"Five functions","d":"Protection of internal structures · prevention of entry of microorganisms · temperature regulation · excretion · production of vitamin D.","s":1},{"t":"Sudoriferous (eccrine) glands","d":"Secrete sweat to maintain body temperature.","s":1},{"t":"Apocrine glands","d":"Become active during PUBERTY; secrete pheromones.","s":1},{"t":"Sebaceous glands","d":"Surround hair follicles; secrete sebum to keep hair and skin moist.","s":1},{"t":"Vellus vs terminal hair","d":"Vellus is short, fine hair covering the body. Terminal is coarse — scalp, pubic, axillary, beard.","s":1},{"t":"Five features of any lesion","d":"Distribution (location) · configuration (shape) · morphology (form and structure) · colour · texture.","s":2},{"t":"Distribution → diagnosis","d":"Generalised/diffuse = allergic reactions. Regional = tinea capitis. Sun-exposed (photodistribution) = skin cancers. Dermatome = herpes zoster. Extensor = psoriasis. Flexor = intertrigo. Intertriginous = skin creases and folds.","s":2},{"t":"Configuration terms","d":"Annular = ring. Arciform = arcs or curves. Confluent = run together. Discrete = remain separate. Grouped = a cluster. Gyrate = twisted, coiled, spiral. Iris/target = bull's eye. Linear = line or stripe. Reticular = lacy or networked. Serpiginous = snake-like.","s":2},{"t":"Herpetiform vs zosteriform","d":"Herpetiform = grouped papules or vesicles arranged as in herpes SIMPLEX. Zosteriform = clustered in a DERMATOMAL distribution, as in herpes zoster. The pair most often swapped.","s":2},{"t":"Primary vs secondary lesion","d":"Primary forms first and results directly from the disease — identifying it is the key to the whole description. Secondary is a change in the primary over time, from disease progression, TREATMENT, or MANIPULATION (picking, scratching).","s":2},{"t":"The 1 cm hinge — three matched pairs","d":"Flat: macule (<1 cm) / patch (>1 cm). Solid elevated: papule (<1 cm) / plaque (>1 cm). Fluid-filled: vesicle (<1 cm) / bulla (>1 cm). Six terms from three pairs — this is why a ruler is on the equipment list.","s":3},{"t":"Nodule vs papule vs tumor","d":"Nodule: elevated, firm, circumscribed, round or ellipsoid, DEEPER in the dermis than a papule, 1–2 cm (Bates: >0.5 cm). Tumor: solid mass >2 cm. Papule: solid, <1 cm.","s":3},{"t":"Plaque","d":"Elevated, flat-topped, firm, rough; plateau-like, occupying a large area compared with its elevation; >1 cm; may be coalesced papules. Example: psoriasis.","s":3},{"t":"Wheal, pustule, cyst","d":"Wheal: elevated irregular cutaneous edema, solid, TRANSIENT, variable diameter (the only transient one). Pustule: superficial elevation filled with PURULENT material, usually <1 cm. Cyst: elevated, circumscribed, ENCAPSULATED, in dermis or subcutis, liquid or semisolid (the only encapsulated one).","s":3},{"t":"Erosion vs ulcer","d":"Erosion: loss of superficial epidermis, does NOT involve dermis; moist but does NOT bleed. Ulcer: deeper loss of epidermis and/or dermis; MAY bleed and scar. Depth determines all three consequences at once.","s":3},{"t":"Crust, fissure, scale, excoriation","d":"Crust: cellular debris, dried serum and blood — a scab; antecedent lesion usually a vesicle, bulla or pustule. Fissure: linear crack (athlete's foot). Scale: thin flake of exfoliated epidermis (dandruff). Excoriation: abrasion or scratch mark, linear or rounded.","s":3},{"t":"Scar vs keloid","d":"Scar (cicatrix): fibrous tissue replacing destroyed tissue; hypertrophic = thick and pink, atrophic = thin and white; does NOT extend beyond the injured area. Keloid: a scar that GROWS BEYOND the wound.","s":3},{"t":"Lichenification & collarette scale","d":"Lichenification: thickening with skin line accentuation from chronic irritation (atopic dermatitis). Collarette scale: fine scale peripherally attached and centrally detached at a lesion's edge (pityriasis rosea).","s":3},{"t":"Corn vs callus; warts","d":"Corn: smaller, usually over a NON-weight-bearing area of the foot, conical keratin pointing toward the dermis. Callus: thickened epidermal keratin, usually on the sole at ball or heel. Verrucae (warts) are caused by human papillomavirus.","s":3},{"t":"Diascopy","d":"Press clear glass or plastic against the skin and look at the lesion under pressure. Colour FADES = vascular engorgement. Does NOT fade = hemorrhage in the skin.","s":4},{"t":"Petechiae / purpura / ecchymosis","d":"Same finding at three sizes, NONE blanching. Petechiae <3 mm. Purpura 3 mm–1 cm. Ecchymosis >1 cm, purple or purplish-blue, fades over time.","s":4},{"t":"Angiomas & telangiectasia","d":"Cherry angioma (Campbell De Morgan spots): dome shaped, bright red to violet/black, ± blanching. Telangiectasia: fine irregular vessels, blanches. Spider angioma: central red macule with radiating arms, blanches.","s":4},{"t":"Triple response of Lewis","d":"Firm stroking (dermatographism) produces: initial red line (capillary dilatation) → reflex flare with broadening erythema (arteriolar dilatation) → linear wheal (transudation of fluid, i.e. edema).","s":4},{"t":"Pressure ulcer stages","d":"I: INTACT skin, erythema failing to blanch, plus change in temperature, consistency, sensation, colour. II: PARTIAL thickness loss (epidermis, dermis or both). III: FULL thickness, subcutaneous necrosis, may extend to but NOT through muscle. IV: full thickness with destruction of tissue, muscle and/or bone.","s":4},{"t":"Tinea by site","d":"Corporis (body) · pedis (foot) · barbae (beard) · cruris (groin) · capitis (scalp) · unguium (nails). Pedis: dry/scaling or macerated fissuring of interdigital spaces. Corporis: sharply demarcated round plaques with CENTRAL CLEARING. Capitis: round scaling patches of alopecia, hairs broken off close to scalp.","s":4},{"t":"Skin malignancies","d":"Basal cell carcinoma: face; translucent PEARLY nodule, depressed centre, raised borders; may ulcerate; non-healing ulcer. Squamous cell carcinoma: face and sun-exposed; red scaling, crusting nodule or plaque that ulcerates and bleeds. Melanoma: irregularly coloured plaque with sharp notches and pigment variation.","s":4},{"t":"Melanoma warning letters","d":"A asymmetry or shape · B border irregularity · C colour variation · D diameter larger than 6 mm · E evolving, elevation · F family history · G growing.","s":4},{"t":"Kaposi's sarcoma","d":"The most frequent neoplasm in patients with acquired immunodeficiency syndrome. Light-coloured lesions coalescing into darker ones; dark blue-purple macules, papules, nodules and plaques; widely disseminated on legs, trunk, arms, neck and head.","s":4},{"t":"Patchy hair loss — three causes","d":"Tinea capitis: SCALING patches, hairs broken close to scalp. Alopecia areata: round patches, 'EXCLAMATION POINT' hairs, chronic inflammatory disease of follicles, associated with autoimmune disorders. Trichotillomania: from an urge to pull, single or multiple patches. Also: androgenic alopecia = male pattern baldness; hirsutism = increased hair in women in a male pattern.","s":4},{"t":"Nail findings","d":"Koilonychia: spoon-shaped concave, plate thins and inverts. Onycholysis: PAINLESS separation of plate from bed starting DISTALLY (chemicals, immersion, fungal, psoriasis, tetracycline, trauma). Pitting: dystrophy of the plate. Terry's nails: proximal white, distal dark. Green = pseudomonas. Brown–black = MELANOMA.","s":4},{"t":"Nail lines, hemorrhages, clubbing","d":"Beau's lines: transverse DEPRESSIONS — halfway up the nail suggests illness about 3 MONTHS ago. Mee's lines: transverse lines. Splinter hemorrhages: distal capillary loop. Subungual hematoma: hemorrhage to the nail plate. Clubbing: nail base-to-finger angle GREATER THAN 180°, fingertip rounded and bulbous. Paronychia: soft tissue infection at cuticle or nail fold; acute is painful and purulent.","s":4},{"t":"IPPA","d":"Inspection, palpation, percussion, auscultation — the same order for EVERY body system except the ABDOMINAL examination. Some systems do not use all four.","s":5},{"t":"Equipment & environment","d":"Ruler, light source, magnifying lens, gloves for open lesions. Patient in a gown so hair, anterior and posterior surfaces, palms and soles, nails and interdigital spaces can all be inspected. Good light, preferably NATURAL — artificial light may distort skin tone.","s":5},{"t":"Six characteristics assessed","d":"Colour · moisture (dryness, sweating, oiliness) · temperature (warmth, coolness) · texture (roughness, smoothness) · mobility and turgor · lesions.","s":5},{"t":"Temperature technique","d":"Use the DORSAL aspect of the hands.","s":5},{"t":"Mobility vs turgor","d":"Mobility: normal skin lifts with ease; reduced mobility = EDEMA. Turgor: normal skin quickly resumes its shape; skin that remains elevated = DEHYDRATION.","s":5},{"t":"Central vs peripheral cyanosis","d":"Central: often inadequate oxygenation IN THE LUNGS. Peripheral: usually inadequate CIRCULATION. Same colour, different organ.","s":5},{"t":"Hair & scalp","d":"Inspect colour, distribution and quantity; palpate for texture. Separate the hair into sections to see the scalp, and inspect BEHIND THE EARS and the OCCIPUT. Should be clean — no lesions, discolorations, flaking or parasites. A magnifying glass aids inspection for lice (nits are tiny white ovoid granules adherent to hairs).","s":5},{"t":"Pruritus is not a diagnosis","d":"It is the sensation causing the desire to scratch. Generalised itching with no obvious reason: dry skin, ageing, pregnancy, uremia, jaundice, lymphomas, leukemias, drug reaction, lice.","s":5},{"t":"History — bugs, drugs, contact","d":"Bugs: family members or contacts with the same, travel. Drugs: systemic medications, over-the-counter AND prescription. Contact: allergens and irritants from hobbies, occupation, environment. Core questions: where it first appeared, what it looked like, how it progressed, associated symptoms, what treatment was tried.","s":5},{"t":"The named virus in viral conjunctivitis","d":"“I&#x27;m not going to test you on it, but adenovirus…” — she uses it for the great-mimicker story. NOTE: CMS I Exam 2 DOES test adenovirus. Different course.","s":6},{"t":"The exophthalmometer","d":"“I am not going to test you on the minutia of how to do that test… it was 20 to 22 millimetres… DON&#x27;T WORRY ABOUT IT.” BUT RECOGNISING EXOPHTHALMOS IS IN — “about exophthalmos and how to recognise it.”","s":6},{"t":"The strabismus diagram","d":"“This is just a visual… that you don&#x27;t have to memorize.” ESO-, EXO- and HYPERTROPIA as concepts stay in.","s":6},{"t":"The corneal reflection test","d":"“We&#x27;ve already done this, so I&#x27;m not gonna test you on it… we already did that in PD1.”","s":6},{"t":"The Adie&#x27;s pupil look-alikes","d":"Dysautonomia/POTS, Shy-Drager, diabetes, amyloidosis — “it&#x27;s not on my test this time.” BUT ADIE&#x27;S PUPIL ITSELF IS IN: “you should know Adie&#x27;s pupil, that could be on my test.”","s":6},{"t":"The Latin behind OD/OS/OU","d":"“I don&#x27;t care if you remember Oculus Sinister or Dexter.” BUT THE ABBREVIATIONS ARE IN — “those are terms that you must remember.” OD RIGHT · OS LEFT · OU BOTH.","s":6},{"t":"DIPLOPIA and the cranial nerves","d":"HORIZONTAL (images SIDE BY SIDE) = palsy of CN III or VI. VERTICAL (images ON TOP of each other) = palsy of CN III or IV. Her shortcut: “THREE FOR BOTH OF THOSE” — CN III is in both patterns; side-by-side is where CN VI joins in.","s":7},{"t":"The RED-EYE CHART — “be very familiar with that chart”","d":"It is a PICTURE on the slide, so it is in no text copy of the deck. Written out in full in the study guide. Scan it by COLUMN: pattern of redness, pain, vision, discharge, pupil, cornea, significance.","s":7},{"t":"RED TEXT ON A SLIDE","d":"“See how this is in red — red&#x27;s important too.” Said of: an ACUTE, SIGNIFICANTLY DILATED PUPIL IS A MEDICAL EMERGENCY, particularly with headache or neurologic signs — UNCAL HERNIATION or POSTERIOR COMMUNICATING ARTERY ANEURYSM.","s":7},{"t":"THE REFERRAL LIST — “please know this list”","d":"Her reason: “because you&#x27;re going to be making those dispos.” EMERGENT (ophtho/ER IMMEDIATELY): SUDDEN VISION LOSS · RETINAL ARTERY OCCLUSION · CHEMICAL BURNS · RUPTURE · ACUTE ANGLE-CLOSURE GLAUCOMA · VITREOUS HAEMORRHAGE. URGENT (ophtho in A DAY OR LESS): ACUTE GLAUCOMA · ORBITAL CELLULITIS · CORNEAL ULCER OR ABRASION · RETINAL DETACHMENT · MACULAR OEDEMA OR HAEMORRHAGE · HYPHAEMA.","s":7},{"t":"The four axes","d":"TIME COURSE · PRECIPITATING FACTORS · PALLIATIVE/EXACERBATING VARIABLES · VISION LOSS.","s":8},{"t":"Laterality and floaters","d":"BILATERAL visual loss → NEUROLOGIC, not ophthalmologic. MULTIPLE NEW flashes/floaters → RETINAL TEAR or VITREOUS HAEMORRHAGE. A SINGLE floater → probably benign.","s":8},{"t":"Tempo","d":"RAPID deterioration → VASCULAR. GRADUAL → CATARACT and the like.","s":8},{"t":"The anaesthetic test","d":"Pain RELIEVED by topical anaesthetic → a SURFACE problem (corneal injury). NOT relieved → a DEEPER source.","s":8},{"t":"Four symptom patterns","d":"ACUTE/UNILATERAL/PAINLESS → retinal vascular occlusion, detachment, vitreous haemorrhage, macular degeneration. ACUTE/UNILATERAL/PAINFUL → cornea + anterior chamber: abrasion/ulcer, uveitis, traumatic hyphaema, acute narrow angle glaucoma. ACUTE/BILATERAL/PAINFUL → THERMAL, RADIATION or CHEMICAL. GRADUAL/PAINLESS → simple glaucoma or cataract.","s":8},{"t":"Eye pain, qualified","d":"With BLINKING → abrasion or foreign body. GRITTY → conjunctivitis. + PHOTOPHOBIA → iris inflammation. + HEADACHE → acute narrow angle glaucoma. On EYE MOTION → optic neuritis. + TEMPORAL pain → temporal arteritis.","s":8},{"t":"Discharge","d":"WATERY or MUCOID → allergic or viral. PURULENT → bacterial.","s":8},{"t":"Don&#x27;t forget to ask","d":"TETANUS STATUS in eye trauma. ACID OR ALKALI after a chemical splash. Systemic: DIABETES, HYPERTENSION and HIV — “HIV is going to affect basically any type of aetiology.”","s":8},{"t":"Order of the exam","d":"INSPECTION → external → cornea/lens/pupils → VISUAL ACUITY (“the vital sign of the eye”) → VISUAL FIELDS → OCULAR MOTILITY → PUPILLARY REACTIONS (CHECK BEFORE DILATING) → corneal reflection → special tests → slit lamp → pressure → ophthalmoscopy.","s":9},{"t":"In trauma","d":"DO NOT PALPATE THE GLOBE.","s":9},{"t":"Lid and brow signs","d":"SCALY brows → seborrhoeic dermatitis. LATERAL SPARSENESS → HYPOTHYROIDISM. PTOSIS → myasthenia gravis, CN III damage, or sympathetic damage (HORNER); senile = weak muscle + relaxed tissue + herniated fat weight. XANTHELASMA on the NASAL lid → lipid disorders.","s":9},{"t":"HORDEOLUM vs CHALAZION on inspection","d":"HORDEOLUM: PAINFUL, AT THE LID&#x27;S EDGE. CHALAZION: chronic, NON-painful, meibomian, generally NOT at the margin — POINTS INSIDE THE LID.","s":9},{"t":"Sclera colour","d":"YELLOW → LIVER DISEASE. BLUE → OSTEOGENESIS IMPERFECTA.","s":9},{"t":"Proptosis technique","d":"STAND BEHIND THE SEATED PATIENT AND LOOK DOWN FROM ABOVE, drawing the lid slightly up. Causes: retrobulbar haemorrhage, orbital cellulitis, orbital tumour, GRAVES.","s":9},{"t":"Nasolacrimal duct test","d":"Look UP; press the lower lid near the MEDIAL CANTHUS just inside the bony rim; watch for regurgitation from the puncta. MUCOPURULENT FLUID = OBSTRUCTION. AVOID if significantly inflamed or tender.","s":9},{"t":"Everting the upper lid","d":"Look DOWN and relax → raise the lid so lashes protrude → grasp and pull DOWN AND FORWARD → stick AT LEAST 1 cm ABOVE THE MARGIN at the upper tarsal border → push down as you raise the edge. DO NOT PRESS ON THE EYEBALL. NEVER EVERT IF GLOBE RUPTURE IS SUSPECTED.","s":9},{"t":"Subconjunctival haemorrhage on exam","d":"PAIN ABSENT · VISION AND PUPIL UNAFFECTED · NO DISCHARGE · CORNEA CLEAR. GLOBE RUPTURE MORE LIKELY in trauma and when the haemorrhage ENCIRCLES THE ENTIRE CORNEA.","s":9},{"t":"Injection pattern","d":"DIFFUSE, MAXIMAL PERIPHERALLY → conjunctivitis. JUST AROUND THE CORNEA → KERATITIS, IRITIS or ACUTE GLAUCOMA.","s":9},{"t":"OD / OS / OU","d":"OD = RIGHT eye. OS = LEFT eye. OU = BOTH. “Terms that you must remember.”","s":10},{"t":"20/200","d":"At 20 FEET the patient reads print a NORMAL eye reads at 200 FEET. THE LARGER THE SECOND NUMBER, THE WORSE THE VISION. Cannot read the chart → document COUNTING FINGERS, HAND MOTION, or LIGHT PERCEPTION.","s":10},{"t":"PINHOLE TEST","d":"Admits only light PERPENDICULAR to the lens, so it need not be bent → CORRECTS ANY REFRACTIVE ERROR. NOT corrected → consider CATARACT, OPTIC NERVE DISEASE or RETINAL DISEASE.","s":10},{"t":"Confrontation fields","d":"STATIC FINGER WIGGLE (arm&#x27;s length, hands 2 ft apart lateral to the ears, into centre of view, each quadrant) PLUS KINETIC RED TARGET (5 mm red-topped pin inward from beyond each quadrant — ask when it FIRST APPEARS RED).","s":10},{"t":"Blind spot","d":"15 DEGREES TEMPORAL to the line of gaze. ENLARGED in GLAUCOMA, OPTIC NEURITIS and PAPILLOEDEMA. A temporal defect in one eye → TEST FOR A NASAL DEFECT IN THE OTHER.","s":10},{"t":"Nystagmus","d":"A FEW BEATS ON LATERAL GAZE IS NORMAL. Bring the finger back into BINOCULAR vision — if it persists there, consider NEUROLOGIC disease.","s":10},{"t":"Lid lag","d":"Rim of SCLERA VISIBLE ABOVE THE IRIS on DOWNWARD gaze. Most often HYPERTHYROIDISM.","s":10},{"t":"Anisocoria","d":"½ to 1 mm difference is COMMON and BENIGN IF THE REACTIONS ARE NORMAL. ABNORMAL: difference &gt; 1 mm, or a POORLY REACTIVE pupil.","s":11},{"t":"SWINGING LIGHT TEST","d":"Indication: ANISOCORIA. ABNORMAL = PARADOXICAL DILATION OF BOTH PUPILS when the light swings to the affected eye, WITH AN INTACT CONSENSUAL REFLEX = RELATIVE AFFERENT PUPILLARY DEFECT = MARCUS GUNN PUPIL = THE LESION IS THE OPTIC NERVE. Mechanism: reduced afferent input → reduced efferent output to BOTH pupils → net dilation.","s":11},{"t":"ADIE&#x27;S TONIC","d":"LARGE, regular, usually UNILATERAL. Light reaction SEVERELY REDUCED/ABSENT. NEAR REACTION PRESENT BUT VERY SLOW. Degeneration of the CILIARY GANGLIA and POSTGANGLIONIC PARASYMPATHETIC fibres.","s":11},{"t":"ARGYLL ROBERTSON","d":"SMALL, UNEQUAL, IRREGULAR. “ACCOMMODATES BUT DOESN&#x27;T REACT.” Classically TERTIARY SYPHILIS, today more often DIABETES; also LYME. Mydriatics dilate it only INCOMPLETELY.","s":11},{"t":"HORNER SYNDROME","d":"PTOSIS · MIOSIS · ANHIDROSIS of the ipsilateral face. THE SMALL PUPIL STILL REACTS BRISKLY to light and near — that is what separates it. Sympathetic supply to pupil AND levator interrupted. CONGENITAL: involved iris is LIGHTER (heterochromia).","s":11},{"t":"CN III PALSY","d":"DILATED pupil FIXED to BOTH light and near, with PTOSIS and LATERAL DEVIATION almost always present.","s":11},{"t":"Three causes of a dilated pupil","d":"Once local eye disease is excluded: (1) COMPRESSION/LESION OF CN III · (2) PARASYMPATHETIC DENERVATION from a ciliary ganglion lesion = ADIE&#x27;S · (3) PHARMACOLOGIC BLOCK of the sphincter.","s":11},{"t":"Oblique lighting — crescent shadow","d":"Light from the TEMPORAL side. NO SHADOW = normal, flat iris, OPEN angle. A SHADOW on the MEDIAL side = iris BOWED FORWARD = NARROW ANGLE = raised risk of NARROW-ANGLE GLAUCOMA.","s":11},{"t":"Corneal scar vs cataract","d":"SCAR: SUPERFICIAL greyish-white corneal opacity. CATARACT: DEEPER, visible ONLY THROUGH THE PUPIL.","s":11},{"t":"DO NOT DILATE if…","d":"SERIAL NEUROLOGIC EXAMS are required · ELDERLY PATIENTS WHO HAVE HAD CATARACT SURGERY · SUSPECTED ACUTE ANGLE-CLOSURE GLAUCOMA. If you dilate: DOCUMENT THE TIME AND THE AGENTS.","s":12},{"t":"NORMAL fundus","d":"YELLOWISH-ORANGE TO CREAM · small disc vessels · SHARP disc margin · cup CENTRAL or slightly TEMPORAL, diameter LESS THAN HALF the disc.","s":12},{"t":"PAPILLOEDEMA","d":"RAISED INTRACRANIAL PRESSURE. PINK, disc SWOLLEN with BLURRED MARGINS, CUP NOT VISIBLE, LOSS OF VESSEL PULSATIONS.","s":12},{"t":"GLAUCOMATOUS CUPPING","d":"Cup ENLARGED, MORE THAN HALF the disc diameter; retinal vessels SINK IN AND AROUND the disc.","s":12},{"t":"OPTIC ATROPHY","d":"WHITE disc, TINY DISC VESSELS ABSENT — death of optic nerve fibres. Seen in OPTIC NEURITIS, MULTIPLE SCLEROSIS, TEMPORAL ARTERITIS.","s":12},{"t":"Trauma mechanics","d":"LARGER objects transfer most energy to the ORBITAL RIM; SMALLER objects may strike the GLOBE directly.","s":12},{"t":"ORBITAL (BLOW-OUT) FRACTURE","d":"SUNKEN EYE · INFRAORBITAL HYPOAESTHESIA (infraorbital nerve) · DIPLOPIA PARTICULARLY ON UPWARD GAZE · decreased motility · sometimes IPSILATERAL NOSEBLEED. Look for ECCHYMOSIS, POINT TENDERNESS, PALPABLE STEP-OFF.","s":12},{"t":"ZYGOMATIC FRACTURE","d":"FLATTENING OF THE MALAR EMINENCE, best seen from BEHIND the seated patient looking down. PAIN ON OPENING THE MOUTH because TEMPORALIS passes MEDIAL to the arch and inserts on the MANDIBLE.","s":12},{"t":"HYPHAEMA","d":"Blood in the ANTERIOR CHAMBER from blunt trauma. Check ACUITY · PUPILS (crescent-like iris defect if torn) · RED REFLEX · INTRAOCULAR PRESSURE · SLIT LAMP.","s":12},{"t":"CORNEAL ABRASION","d":"EVERT THE UPPER LID — a foreign body in the upper tarsal conjunctiva scratches with every blink. A HAZY CORNEA SUGGESTS BACTERIAL INFECTION. TOPICAL ANAESTHETIC IS FOR DIAGNOSIS, NOT TREATMENT.","s":12},{"t":"CORNEAL ULCER","d":"HERPES SIMPLEX ULCERS ARE NOT VERY PAINFUL. Ophthalmoscope at +40 DIOPTRES may reveal it, but FLUORESCEIN IS MORE SENSITIVE for early ulcers. Fluorescein is taken up by cornea DEVOID OF EPITHELIUM.","s":12}],"map":{"physical-diagnosis-2-exam-1-clinical-reasoning-documentation-quiz":[2,5,0,1,2,0,-1,0,3,0,6,-1,-1,-1,6],"physical-diagnosis-2-exam-1-dermatology-quiz-version-2":[7,14,30,45,-1,13,41,16,16,39,-1,16,13,30,31,43,16,29,-1,16,19,-1,35,32,14,35,46,10,44,43],"physical-diagnosis-2-exam-1-dermatology-quiz":[9,30,28,23,14,16,-1,44,37,16,8,31,29,-1,37,40,-1,-1,11,34,26,33,13,16,-1,15,16,36,13,16],"physical-diagnosis-2-exam-1-ocular-exam-quiz-version-2":[54,61,69,65,62,63,78,50,79,75,-1,100,62,67,53,76,-1,-1,68,54,-1,54,-1,66,61,-1,53,-1,54,65],"physical-diagnosis-2-exam-1-ocular-exam-quiz":[98,74,86,85,62,-1,61,53,80,54,86,56,-1,85,72,54,101,63,65,-1,62,-1,-1,71,54,73,66,-1,-1,56]}};
